-- 관리자 스티커 카탈로그
-- 실행 전 백업 후 적용한다. 애플리케이션은 이 SQL을 자동 실행하지 않는다.

CREATE TABLE diary_sticker_categories (
    id BIGINT NOT NULL AUTO_INCREMENT,
    code VARCHAR(80) NOT NULL,
    name VARCHAR(50) NOT NULL,
    display_order INT NOT NULL DEFAULT 1,
    is_visible TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_diary_sticker_categories_code (code),
    UNIQUE KEY uk_diary_sticker_categories_name (name),
    KEY idx_diary_sticker_categories_display (is_visible, display_order, id),
    CONSTRAINT chk_diary_sticker_categories_display_order CHECK (display_order >= 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE diary_stickers (
    id BIGINT NOT NULL AUTO_INCREMENT,
    catalog_key VARCHAR(100) NOT NULL,
    name VARCHAR(100) NOT NULL,
    category_id BIGINT NOT NULL,
    image_url VARCHAR(500) NOT NULL,
    sticker_type VARCHAR(20) NOT NULL,
    access_tier VARCHAR(20) NOT NULL DEFAULT 'FREE',
    is_visible TINYINT(1) NOT NULL DEFAULT 1,
    display_order INT NOT NULL DEFAULT 1,
    collection_code VARCHAR(20) NOT NULL DEFAULT 'default',
    tape_style VARCHAR(20) NOT NULL DEFAULT 'NORMAL',
    repeat_left_url VARCHAR(500) DEFAULT NULL,
    repeat_center_url VARCHAR(500) DEFAULT NULL,
    repeat_right_url VARCHAR(500) DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_diary_stickers_catalog_key (catalog_key),
    UNIQUE KEY uk_diary_stickers_image_url (image_url),
    KEY idx_diary_stickers_picker (category_id, is_visible, display_order, id),
    CONSTRAINT fk_diary_stickers_category FOREIGN KEY (category_id)
        REFERENCES diary_sticker_categories (id),
    CONSTRAINT chk_diary_stickers_type CHECK (sticker_type IN ('NORMAL', 'MASKING_TAPE')),
    CONSTRAINT chk_diary_stickers_access_tier CHECK (access_tier IN ('FREE', 'PREMIUM')),
    CONSTRAINT chk_diary_stickers_tape_style CHECK (tape_style IN ('NORMAL', 'TRANSLUCENT', 'CLEAR')),
    CONSTRAINT chk_diary_stickers_display_order CHECK (display_order >= 1),
    CONSTRAINT chk_diary_stickers_repeat_urls CHECK (
        (repeat_left_url IS NULL AND repeat_center_url IS NULL AND repeat_right_url IS NULL)
        OR
        (repeat_left_url IS NOT NULL AND repeat_center_url IS NOT NULL AND repeat_right_url IS NOT NULL)
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 현재 JSON 카테고리의 code와 표시 순서를 보존한다.
INSERT INTO diary_sticker_categories (code, name, display_order, is_visible) VALUES
('travel', '여행', 1, 1),
('landmark', '랜드마크', 2, 1),
('emotion', '감정', 3, 1),
('food', '음식', 4, 1),
('nature', '자연', 5, 1),
('weather', '날씨', 6, 1),
('decoration', '장식', 7, 1),
('lettering', '레터링', 8, 1),
('season', '계절', 9, 1),
('masking-tape', '마스킹테이프', 10, 1)
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    display_order = VALUES(display_order);

